const makeVocabulary = (
  id: string,
  category: VocabularyCategory,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  sentence: string,
  sentenceKana: string,
  translation: string,
  tags: string[] = [category],
): VocabularyItem => ({
  id,
  category,
  japanese,
  kana,
  romaji,
  meaning,
  sentence,
  sentenceKana,
  translation,
  level: "基础",
  tags,
});

const makeN3Vocabulary = (
  id: string,
  category: VocabularyCategory,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  sentence: string,
  sentenceKana: string,
  translation: string,
  tags: string[] = [category, "N3"],
): VocabularyItem => ({
  id,
  category,
  japanese,
  kana,
  romaji,
  meaning,
  sentence,
  sentenceKana,
  translation,
  level: "N3",
  tags,
});

const makeExamVocabulary = (
  id: string,
  level: ExamVocabularyLevel,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  sentence: string = `「${japanese}」はよく出ます。`,
  sentenceKana: string = `「${kana}」はよくでます。`,
  translation: string = `“${meaning}”是常见考试词。`,
  tags: string[] = ["考试单词", level, "JLPT", "综合"],
): VocabularyItem => ({
  id,
  category: "考试单词",
  japanese,
  kana,
  romaji,
  meaning,
  sentence,
  sentenceKana,
  translation,
  level,
  tags,
});

const makeExamTerm = (
  id: string,
  level: ExamVocabularyLevel,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  topics: string[] = ["综合"],
): VocabularyItem =>
  makeExamVocabulary(
    id,
    level,
    japanese,
    kana,
    romaji,
    meaning,
    undefined,
    undefined,
    undefined,
    ["考试单词", level, "JLPT", ...topics],
  );

type ExamTermSeed = readonly [
  idSuffix: string,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  topics: readonly string[],
];

const makeExamTermGroup = (
  prefix: string,
  level: ExamVocabularyLevel,
  terms: readonly ExamTermSeed[],
): VocabularyItem[] =>
  terms.map(([idSuffix, japanese, kana, romaji, meaning, topics]) =>
    makeExamTerm(`${prefix}-${idSuffix}`, level, japanese, kana, romaji, meaning, [...topics]),
  );

const makeCommonTerm = (
  id: string,
  category: VocabularyCategory,
  japanese: string,
  kana: string,
  romaji: string,
  meaning: string,
  level: VocabularyLevel = "基础",
  tags: string[] = [category],
): VocabularyItem => ({
  id,
  category,
  japanese,
  kana,
  romaji,
  meaning,
  sentence: `「${japanese}」はよく使います。`,
  sentenceKana: `「${kana}」はよくつかいます。`,
  translation: `“${meaning}”是常用词。`,
  level,
  tags,
});

